// console.log('===', index)

const element = $('webhook').first().json.body.storyboard_prompts[index]

return {
  data: {
    "prompt": element.prompt,
    "duration": element.duration
  }
}

const storyboard = $('webhook').first().json.body.storyboard_prompts

const voice_list = $input.first().json.data.map(item => {
  return {
    "text": item.text,
    "audio_length": item.audio_length,
    "start_time": item.start_time,
    "end_time": item.end_time
  }
})

return {
  "data": {
    storyboard,
    voice_list
  }
}

const audio_path_list = $('生成音频后字段整理').first().json.data
const video_path_list = $('生成分镜视频后字段整理').first().json.videos_filepath
return {
  "data": {
    "video_path_list": video_path_list,
    "audio_path_list": audio_path_list,
    "subtitle_filename": $input.first().json.fileName
  }
};

